<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT p.id,p.name,pp.price FROM products p JOIN product_prices pp ON pp.product_id=p.id AND pp.level_id=? WHERE p.is_active=1');$q->execute([$u['level_id']]);$ps=$q->fetchAll();$title='Order IMEI';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Create IMEI order</h1><p class="page-sub">Pilih layanan dan masukkan IMEI 15 digit.</p></div><div class="grid lg:grid-cols-[1fr_.55fr] gap-5 mt-6"><form id="f" class="saas-card p-5 sm:p-6 space-y-5"><div><label class="text-sm font-semibold">Service</label><select class="field mt-2" name="product_id" required><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> — Rp<?=number_format($p['price'],0,',','.')?></option><?php endforeach?></select></div><div><div class="flex justify-between"><label class="text-sm font-semibold">IMEI</label><span data-imei-count class="text-xs text-zinc-500">0/15</span></div><input class="field font-mono mt-2 text-base tracking-wider" name="imei" placeholder="35XXXXXXXXXXXXX" maxlength="15" inputmode="numeric" pattern="[0-9]{15}" oninput="cleanImei(this)" required><div data-imei-status class="text-xs text-zinc-500 mt-2">IMEI harus tepat 15 digit</div></div><button class="btn btn-dark w-full sm:w-auto"><i data-lucide="arrow-right"></i>Create order</button></form><aside class="saas-card p-5 h-fit"><i data-lucide="shield-check"></i><h3 class="font-semibold mt-3">Before you submit</h3><p class="text-sm text-zinc-500 mt-2 leading-6">Pastikan IMEI benar. Sistem akan menjalankan pemeriksaan sesuai konfigurasi layanan sebelum diteruskan ke provider.</p></aside></div><script>f.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),j=await r.json();Swal.fire(j.ok?'Order created':'Order failed',j.ok?j.data.order_number:j.message,j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>